volatile unsigned long pulses = 0;
void IRAM_ATTR isr() { pulses++; }
void setup() {
    Serial.begin(115200);
    pinMode({{hall_pin}}, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt({{hall_pin}}), isr, FALLING);
}
void loop() {
    delay(1000);
    noInterrupts();
    unsigned long p = pulses; pulses = 0;
    interrupts();
    float rpm = (p * 60.0f) / {{pulses_per_rev}};
    Serial.printf("RPM=%.1f\n", rpm);
}
